import fs from 'node:fs';
import path from 'node:path';

function read(file) { return fs.readFileSync(file, 'utf8'); }
function write(file, content) { fs.writeFileSync(file, content); }
function replaceOnce(file, before, after) {
  const current = read(file);
  const index = current.indexOf(before);
  if (index < 0) throw new Error(`Anchor not found in ${file}: ${before.slice(0, 120)}`);
  if (current.indexOf(before, index + before.length) >= 0) throw new Error(`Anchor not unique in ${file}: ${before.slice(0, 120)}`);
  write(file, current.slice(0, index) + after + current.slice(index + before.length));
}
function insertAfter(file, anchor, addition) {
  const current = read(file);
  const index = current.indexOf(anchor);
  if (index < 0) throw new Error(`Anchor not found in ${file}: ${anchor.slice(0, 120)}`);
  if (current.indexOf(anchor, index + anchor.length) >= 0) throw new Error(`Anchor not unique in ${file}`);
  const end = index + anchor.length;
  write(file, current.slice(0, end) + addition + current.slice(end));
}

